#include <iostream>
namespace geo { const double PI = 3.14159; double area(double r) { return PI * r * r; } }
namespace geo { namespace unit { const char *NAME = "cm"; } }  // reopened + nested
namespace { int hidden = 7; }         // anonymous: visible in this file only
using std::cout;                      // using-declaration: one name
int main() {
    cout << geo::area(2.0) << "\n";   // qualified with scope resolution ::
    cout << geo::unit::NAME << "\n";  // nested namespace
    using namespace geo;              // using-directive: all names of geo
    cout << PI << " " << hidden << std::endl;
    return 0;
}

int    area(int s)            { return s * s; }        // square
int    area(int l, int b)     { return l * b; }        // rectangle
double area(double r)         { return 3.14 * r * r; } // circle
// double area(int s) { ... }  // ERROR: differs only in return type
int main() {
    area(3);        // exact match      -> area(int)
    area(3, 4);     // two args         -> area(int, int)
    area(2.5);      // exact match      -> area(double)
    area(2.5f);     // float promotes to double -> area(double)
    // area(3L);    // long: int or double? AMBIGUOUS -> compile error
    return 0;
}

void swap(int &a, int &b) { int t = a; a = b; b = t; }  // aliases of caller's vars
void print(const std::string &s) { std::cout << s; }      // read-only, no copy
int &larger(int &x, int &y) { return x > y ? x : y; }     // returns an lvalue alias
int &bad() { int local = 5; return local; }               // DANGLING: local dies

int main() {
    int p = 1, q = 2;
    swap(p, q);              // p = 2, q = 1; no & at the call site
    int &r = p;              // r must be initialised; it can never re-bind
    r = 10;                  // p is now 10
    larger(p, q) = 0;        // assignment through the returned reference: p = 0
    return 0;
}

#include <iostream>
int base = 2;
int scale(int x, int k = base) { return x * k; }
int &pick(int &a, int &b) { return a > b ? a : b; }
int main() {
    int p = 3, q = 7;
    pick(p, q) = scale(p);
    base = 10;
    std::cout << p << " " << q << " " << scale(1) << "\n";
    return 0;
}

