class Rectangle {
private:                       // hidden state (private is the default anyway)
    double w, h;
public:                        // the interface
    void set(double w0, double h0) { w = w0; h = h0; }
    double area() const { return w * h; }
};                             // do not forget this semicolon

int main() {
    Rectangle r;               // object r: 16 bytes of data (two doubles)
    r.set(3.0, 4.0);
    std::cout << r.area();     // 12
    // r.w = 5;                // ERROR: w is private
}

class Circle {
    double r;
public:
    double area() const { return 3.14159 * r * r; }  // inside: implicitly inline
    void setR(double v);                              // declared here ...
    double getR() const;
};

void Circle::setR(double v) { if (v >= 0) r = v; }   // ... defined outside with ::
double Circle::getR() const { return r; }            // Class::name links it back

// inline double Circle::getR() const { return r; }  // outside but still inline

class Account {
    std::string owner;
    double balance;                   // invariant: never negative
public:
    Account(std::string o, double b = 0) : owner(o), balance(b) {}
    bool withdraw(double amt) {       // mutator with validation
        if (amt <= 0 || amt > balance) return false;
        balance -= amt; return true;
    }
    void deposit(double amt) { if (amt > 0) balance += amt; }
    double getBalance() const { return balance; }   // accessor
};
Account acc("Sita", 500);
acc.withdraw(700);                    // refused; balance stays 500
std::cout << acc.getBalance();        // 500

#include <iostream>
using namespace std;
class Wallet {
public:
    int cash;
};
void spend(Wallet w)     { w.cash -= 30; }
void spendRef(Wallet &w) { w.cash -= 30; }
Wallet refill(Wallet w)  { w.cash += 100; return w; }
int main() {
    Wallet a; a.cash = 50;
    spend(a);    cout << a.cash << " ";
    spendRef(a); cout << a.cash << " ";
    Wallet b = refill(a); cout << a.cash << " " << b.cash;
}

