public:
    Box() : len(0) { cout << "default "; }            // default constructor
    Box(int l) : len(l) { cout << "param "; }         // parameterised
    Box(const Box &b) : len(b.len) { cout << "copy "; } // copy constructor
    ~Box() { cout << "destroy" << len << " "; }       // destructor
};
