class Counter {
    static int count;                       // declaration: one copy for the class
    int id;
public:
    Counter()  { id = ++count; }             // every object bumps the shared count
    ~Counter() { --count; }
    static int alive() { return count; }     // static function: no object needed
};
int Counter::count = 0;                      // DEFINITION, outside, exactly once
int main() {
    cout << Counter::alive();                // 0 -- called before any object exists
    Counter a, b;
    { Counter c; cout << " " << Counter::alive(); }   // 3
    cout << " " << a.alive();                // 2 (c destroyed); output: 0 3 2
}

class Temp {
    double c;
    mutable int reads;                        // mutable: changeable even in const fn
public:
    Temp(double v) : c(v), reads(0) {}
    double get() const { ++reads; return c; } // const fn: may not change c
    void set(double v) { c = v; }             // non-const fn
    // double bad() const { c = 0; return c; } // ERROR: assigns in a const fn
};
int main() {
    const Temp t(36.6);      // const object: state frozen after construction
    t.get();                 // OK: const function
    // t.set(40);            // ERROR: non-const function on a const object
    Temp u(20); u.set(25); u.get();   // non-const object may call both
}

class Num {
    int v;
public:
    Num(int v) { this->v = v; }             // parameter shadows member: use this->
    Num &add(int k) { v += k; return *this; }   // return the object itself ...
    Num &dbl()      { v *= 2; return *this; }   // ... so calls can be chained
    bool same(const Num &o) const { return this == &o; }  // identity test
    int get() const { return v; }
};
int main() {
    Num n(1);
    n.add(2).dbl().add(1);      // (1 + 2) * 2 + 1 = 7
    cout << n.get() << " " << n.same(n);   // 7 1
}

class Vec {
    double x, y;
public:
    Vec(double a, double b) : x(a), y(b) {}
    friend double dot(const Vec &p, const Vec &q);       // friend function
    friend std::ostream &operator<<(std::ostream &, const Vec &);
    friend class Printer;                                // friend class
};
double dot(const Vec &p, const Vec &q) { return p.x * q.x + p.y * q.y; }  // no ::
std::ostream &operator<<(std::ostream &os, const Vec &v)
{ return os << "(" << v.x << ", " << v.y << ")"; }
class Printer { public: void show(const Vec &v) { std::cout << v.x << v.y; } };
int main() { Vec a(1, 2), b(3, 4); std::cout << dot(a, b) << a; }   // 11(1, 2)

